const safeFiles=visibleFiles;
const sortedRecords=p=>[...(p.records||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.updatedAt||b.createdAt).localeCompare(String(a.updatedAt||a.createdAt)));
const sourceText=value=>typeof value==='string'?value:Array.isArray(value)?value.map(sourceText).join('\n'):value?.path ? `${value.path}${value.description?` — ${value.description}`:''}` : value?.label||value?.text||value?.description||'';
const automaticRecord=r=>r?.managedBy==='codex-auto'||r?.autoGenerated===true;
const summaryFor=(p,date)=>(p.codex?.dailySummaries||[]).find(summary=>summary.date===date);
const issueKeys=item=>new Set([item?.issueKey,...(Array.isArray(item?.relatedIssueKeys)?item.relatedIssueKeys:[])].filter(key=>typeof key==='string'&&key));
const summaryDismissed=(p,date,item)=>{const keys=issueKeys(item);return (p.codex?.summaryDismissals||[]).some(entry=>entry.threadId===p.codex?.threadId&&entry.date===date&&keys.has(entry.issueKey));};
const summaryRecordFor=(p,date,item)=>{const keys=issueKeys(item),priority=record=>(record.manual?4:0)+(record.confirmed?2:0)+(!automaticRecord(record)?1:0);return (p.records||[]).filter(record=>record.date===date&&keys.has(record.issueKey)).sort((a,b)=>priority(b)-priority(a)||String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')))[0];};
const brief=(text,length=150)=>{const value=String(text||'').replace(/\s+/g,' ').trim();return value.length>length?value.slice(0,length)+'…':value;};
const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value);
